"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { Button } from "../../base/buttons/button";
import { CloseButton } from "../../base/buttons/close-button";
import { Checkbox } from "../../base/checkbox/checkbox";
import { CheckboxCard } from "../../base/checkbox/checkbox-card";
import { TextField, InputBase } from "../../base/input/input";
import { Kbd } from "../../base/kbd/kbd";
import { PillTab, PillTabList } from "../../base/tabs/pill-tab";
import { CardSurface } from "../charts/card-surface";
import { cx } from "@/lib/cx";

export type QuestionnaireSelect = "multiple" | "single";
export interface QuestionnaireOption { value: string; label: ReactNode; description?: ReactNode }
export interface QuestionnaireQuestion {
  id: string;
  question: ReactNode;
  options: readonly QuestionnaireOption[];
  other?: boolean | { placeholder?: string };
  stepLabel?: ReactNode;
  select?: QuestionnaireSelect;
}
export interface QuestionnaireAnswer { values: string[]; other?: string }
export type QuestionnaireAnswers = Record<string, QuestionnaireAnswer>;
export interface QuestionnaireProps {
  questions: readonly QuestionnaireQuestion[];
  select?: QuestionnaireSelect;
  answers?: QuestionnaireAnswers;
  defaultAnswers?: QuestionnaireAnswers;
  onAnswersChange?: (answers: QuestionnaireAnswers) => void;
  step?: number;
  defaultStep?: number;
  onStepChange?: (step: number) => void;
  advanceDelay?: number;
  onComplete?: (answers: QuestionnaireAnswers) => void;
  onDismiss?: () => void;
  labels?: { previous?: string; next?: string; complete?: string; other?: string; otherPlaceholder?: string; dismiss?: string; steps?: string };
  className?: string;
}
const easing = [.22, 1, .36, 1] as const;
const row = "group flex w-full items-center gap-4 rounded-2xl border border-border-button-default bg-background-primary-default py-[9px] pe-[19px] ps-[11px] text-start transition-colors duration-150 ease outline-none";
const useClientLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;
function NumberKey({ children, selected = false }: { children: ReactNode; selected?: boolean }) {
  return <Kbd aria-hidden className={cx("shrink-0 rounded-sm px-[5px] py-0.5 text-body-2-medium text-text-primary transition-colors duration-150 ease group-hover:bg-questionnaire-key-hover-background", selected ? "bg-questionnaire-key-hover-background" : "bg-questionnaire-key-background")}>{children}</Kbd>;
}
export function Questionnaire({ questions, select = "multiple", answers: controlledAnswers, defaultAnswers = {}, onAnswersChange, step: controlledStep, defaultStep = 0, onStepChange, advanceDelay = 180, onComplete, onDismiss, labels = {}, className }: QuestionnaireProps) {
  const [localAnswers, setLocalAnswers] = useState(defaultAnswers), [localStep, setLocalStep] = useState(defaultStep);
  const [otherDrafts, setOtherDrafts] = useState<Record<string, string>>({});
  const answers = controlledAnswers ?? localAnswers;
  const step = Math.max(0, Math.min(questions.length - 1, Math.floor(controlledStep ?? localStep) || 0));
  const question = questions[step], single = (question?.select ?? select) === "single";
  const answer = answers[question?.id] ?? { values: [] };
  const latest = useRef({ answers, onComplete }); latest.current = { answers, onComplete };
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const clearAdvance = () => { if (timer.current !== undefined) clearTimeout(timer.current); timer.current = undefined; };
  useEffect(() => clearAdvance, [step, question?.id]);
  const content = useRef<HTMLDivElement>(null), otherInput = useRef<HTMLInputElement>(null);
  const [height, setHeight] = useState<number>();
  const reduced = useReducedMotion(), id = useId(), heading = `${id}-${question?.id}`;
  const direction = useRef({ step, value: 1 });
  if (direction.current.step !== step) direction.current = { step, value: step > direction.current.step ? 1 : -1 };
  useClientLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setHeight(element.offsetHeight + 8);
    measure(); const observer = new ResizeObserver(measure); observer.observe(element);
    return () => observer.disconnect();
  }, [step, question?.id, questions]);
  const mounted = useRef(false);
  useEffect(() => {
    if (mounted.current) content.current?.focus({ preventScroll: true });
    mounted.current = true;
  }, [step]);
  const change = (next: QuestionnaireAnswer) => {
    const updated = { ...answers, [question.id]: next };
    latest.current.answers = updated;
    if (controlledAnswers === undefined) setLocalAnswers(updated);
    onAnswersChange?.(updated);
  };
  const navigate = (next: number) => {
    clearAdvance();
    const bounded = Math.max(0, Math.min(questions.length - 1, next));
    if (bounded === step) return;
    if (controlledStep === undefined) setLocalStep(bounded);
    onStepChange?.(bounded);
  };
  const advance = () => {
    clearAdvance();
    if (step === questions.length - 1) latest.current.onComplete?.(latest.current.answers);
    else navigate(step + 1);
  };
  const pick = (value: string) => {
    clearAdvance();
    const selected = new Set(single ? [value] : answer.values.includes(value) ? answer.values.filter(item => item !== value) : [...answer.values, value]);
    change({ values: question.options.filter(option => selected.has(option.value)).map(option => option.value), ...(!single && answer.other !== undefined ? { other: answer.other } : {}) });
    if (single) timer.current = setTimeout(advance, reduced ? 0 : Math.max(0, advanceDelay));
  };
  if (!question) return null;
  const otherLabel = labels.other ?? "Other", otherValue = answer.other ?? otherDrafts[question.id] ?? "";
  return <CardSurface role="group" aria-labelledby={heading} padding="none" tone="primary" className={cx("relative flex w-full max-w-[648px] flex-col gap-2.5 overflow-hidden rounded-[20px] p-3 shadow-[0_4px_2px_rgba(0,0,0,0.02),0_1px_0.5px_rgba(0,0,0,0.05)]", className)} onKeyDown={event => {
    if (!single || event.altKey || event.ctrlKey || event.metaKey || event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement || (event.target instanceof HTMLElement && event.target.isContentEditable)) return;
    const index = Number(event.key) - 1;
    if (!/^[1-9]$/.test(event.key)) return;
    if (index < question.options.length) { event.preventDefault(); pick(question.options[index].value); }
    else if (question.other && index === question.options.length) { event.preventDefault(); otherInput.current?.focus(); }
  }}>
    <motion.div className="relative -mx-3 -my-1 overflow-hidden px-3 py-1" animate={{ height }} transition={{ duration: reduced ? 0 : .38, ease: easing }}>
      <AnimatePresence initial={false} mode="popLayout" custom={direction.current.value}>
        <motion.div key={question.id} data-questionnaire-step={question.id} ref={node => { if (node) content.current = node; else if (content.current?.dataset.questionnaireStep === question.id) content.current = null; }} tabIndex={-1} className="flex flex-col gap-2.5 outline-none" custom={direction.current.value}
          variants={{ enter: (d: number) => ({ x: d * 28, opacity: 0, filter: "blur(4px)" }), landed: { x: 0, opacity: 1, filter: "blur(0px)" }, leave: (d: number) => ({ x: -d * 28, opacity: 0, filter: "blur(4px)" }) }}
          initial="enter" animate="landed" exit="leave" transition={{ duration: reduced ? 0 : .32, ease: easing }}>
          <div className="flex min-h-5 items-start ps-0.5 pe-7"><p id={heading} className="text-body-medium text-text-primary">{question.question}</p></div>
          <div role="group" aria-labelledby={heading} className="flex flex-col gap-2">
            {question.options.map((option, index) => single ?
              <Button key={option.value} unstyled aria-pressed={answer.values.includes(option.value)} onClick={() => pick(option.value)} className={cx(row, "cursor-pointer select-none hover:bg-background-primary-hover focus-visible:ring-2 focus-visible:ring-border-focus-ring", answer.values.includes(option.value) && "border-border-button-hover bg-background-primary-hover")}>
                <span className="flex min-w-0 flex-1 flex-col"><span className="text-body-medium text-text-primary">{option.label}</span>{option.description !== undefined && <span className="text-body-regular text-text-secondary">{option.description}</span>}</span><NumberKey selected={answer.values.includes(option.value)}>{index + 1}</NumberKey>
              </Button> : <CheckboxCard key={option.value} variant="compact" title={option.label} description={option.description} isSelected={answer.values.includes(option.value)} onChange={() => pick(option.value)} />)}
            {question.other && <div className={cx(row, "cursor-text hover:bg-background-primary-hover has-[input:focus]:border-border-button-hover has-[input:focus]:bg-background-primary-hover", single && answer.other !== undefined && "border-border-button-hover bg-background-primary-hover")} onClick={event => { if (!(event.target instanceof HTMLElement && event.target.closest("label"))) otherInput.current?.focus(); }}>
              <span className="flex min-w-0 flex-1 flex-col"><span className="text-body-medium text-text-primary">{otherLabel}</span>
                <TextField aria-label={otherLabel} className="w-full" value={otherValue} onChange={value => { clearAdvance(); setOtherDrafts(previous => ({ ...previous, [question.id]: value })); change({ values: single ? [] : answer.values, other: value }); }}>
                  <InputBase appearance="plain" data-questionnaire-step={question.id} ref={node => { if (node) otherInput.current = node; else if (otherInput.current?.dataset.questionnaireStep === question.id) otherInput.current = null; }} placeholder={typeof question.other === "object" ? question.other.placeholder ?? labels.otherPlaceholder ?? "Enter your custom answer here" : labels.otherPlaceholder ?? "Enter your custom answer here"} onKeyDown={event => { if (single && event.key === "Enter" && otherValue.trim()) { event.preventDefault(); event.stopPropagation(); advance(); } }} />
                </TextField>
              </span>
              {single ? <NumberKey selected={answer.other !== undefined}>{question.options.length + 1}</NumberKey> : <Checkbox aria-label={otherLabel} className="shrink-0 cursor-pointer py-1" isSelected={answer.other !== undefined} onChange={selected => { clearAdvance(); change({ values: answer.values, ...(selected ? { other: otherValue } : {}) }); }} />}
            </div>}
          </div>
        </motion.div>
      </AnimatePresence>
    </motion.div>
    {onDismiss && <CloseButton size="xs" aria-label={labels.dismiss ?? "Dismiss"} onClick={onDismiss} className="absolute end-3 top-3" />}
    <div className="flex items-start justify-between gap-4 pt-0.5">
      <PillTabList aria-label={labels.steps ?? "Steps"} className="flex-wrap gap-2">{questions.map((item, index) => <PillTab key={item.id} isSelected={index === step} onSelect={() => navigate(index)}>{item.stepLabel ?? `Step ${index + 1}`}</PillTab>)}</PillTabList>
      <div className="flex shrink-0 items-center justify-end gap-2"><Button size="small" variant="secondary" disabled={step === 0} onClick={() => navigate(step - 1)}>{labels.previous ?? "Previous"}</Button><Button size="small" onClick={advance}>{step === questions.length - 1 ? labels.complete ?? "Done" : labels.next ?? "Next"}</Button></div>
    </div>
  </CardSurface>;
}

// @zeus-internal
import { cx } from "@/lib/cx";
export const INPUT_FIELD_SURFACE = "relative flex w-full items-center rounded-2lg bg-background-tertiary-default text-foreground-icon-tertiary ring-2 ring-inset ring-transparent transition-[background-color,box-shadow,color] duration-[var(--input-transition-ms)] ease";
export function inputFieldStateClasses({ isFocusWithin, isHovered, isDisabled, isInvalid }: {
  isFocusWithin: boolean;
  isHovered: boolean;
  isDisabled: boolean;
  isInvalid: boolean;
}) {
  return cx(
    isHovered && !isFocusWithin && !isDisabled && !isInvalid && "ring-border-button-hover",
    isFocusWithin && !isDisabled && !isInvalid && "ring-border-button-active",
    isDisabled && "bg-input-disabled-background text-input-disabled-foreground",
    isInvalid && "bg-background-tertiary-error text-foreground-icon-error",
  );
}
